import requests, pandas as pd, numpy as np, matplotlib.pyplot as plt

# HPO annotations for the disease
rows=[]
for url in ["https://ontology.jax.org/api/network/annotation/OMIM:615074",
            "https://hpo.jax.org/api/hpo/disease/OMIM:615074"]:
    try:
        j=requests.get(url,timeout=60).json()
        cats=j.get("categories") or {}
        if cats:
            for cat,terms in cats.items():
                for t in terms:
                    rows.append(dict(cat=cat,hpo=t.get("id"),name=t.get("name"),
                                     freq=t.get("frequency") or t.get("metadata",{}).get("frequency")))
        elif "catTermsMap" in j:
            for blk in j["catTermsMap"]:
                for t in blk["terms"]:
                    rows.append(dict(cat=blk["catLabel"],hpo=t["ontologyId"],name=t["name"],freq=t.get("frequency")))
        if rows: print("source:",url); break
    except Exception as e: print("fail",url,e)
H=pd.DataFrame(rows)
print(H.shape)
if len(H):
    for c,g in H.groupby("cat"):
        print("\n##",c)
        for _,r in g.iterrows(): print(f"  {r.hpo}  {r['name']}  freq={r.freq}")

